#include <iostream>
#include <iomanip>

int main() {
    // Khởi tạo mảng ký tự với chuỗi mẫu (tự động thêm '\0')
    char greeting[] = "string literal";

    // Khởi tạo mảng có kích thước cố định để đọc dữ liệu
    constexpr size_t BUFFER_SIZE = 20;
    char inputBuffer[BUFFER_SIZE] = {};

    // Giới hạn độ dài nhập để ngăn ngừa tràn bộ đệm
    if (std::cin >> std::setw(BUFFER_SIZE) >> inputBuffer) {
        std::cout << "inputBuffer is: " << inputBuffer << "\n";
        std::cout << "greeting is: " << greeting << "\n";
        std::cout << "inputBuffer with spaces between characters is:\n";

        for (size_t i = 0; i < BUFFER_SIZE && inputBuffer[i] != '\0'; ++i) {
            std::cout << inputBuffer[i] << ' ';
        }
        std::cout << "\n";
    }
    return 0;
}

#include <iostream>

void staticArrayDemo() {
    // Khởi tạo một lần duy nhất lúc khởi động, mặc định bằng 0
    static int array1[3];

    std::cout << "Values on entering staticArrayDemo:\n";
    for (size_t i = 0; i < 3; ++i) {
        std::cout << "array1[" << i << "] = " << array1[i] << "  ";
    }

    std::cout << "\nValues on exiting staticArrayDemo:\n";
    for (size_t i = 0; i < 3; ++i) {
        array1[i] += 5;
        std::cout << "array1[" << i << "] = " << array1[i] << "  ";
    }
    std::cout << "\n";
}

void automaticArrayDemo() {
    // Khởi tạo lại mỗi khi hàm được gọi
    int array2[3] = {1, 2, 3};

    std::cout << "Values on entering automaticArrayDemo:\n";
    for (size_t i = 0; i < 3; ++i) {
        std::cout << "array2[" << i << "] = " << array2[i] << "  ";
    }

    std::cout << "\nValues on exiting automaticArrayDemo:\n";
    for (size_t i = 0; i < 3; ++i) {
        array2[i] += 5;
        std::cout << "array2[" << i << "] = " << array2[i] << "  ";
    }
    std::cout << "\n";
}

int main() {
    std::cout << "First call to each function:\n";
    staticArrayDemo();
    automaticArrayDemo();

    std::cout << "\nSecond call to each function:\n";
    staticArrayDemo();
    automaticArrayDemo();

    return 0;
}
